#include <mpi.h>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

#include <pagmo/algorithm.hpp>
#include <pagmo/algorithms/de.hpp>
#include <pagmo/archipelago.hpp>
#include <pagmo/problem.hpp>
#include <pagmo/problems/rosenbrock.hpp>

#include "provenance.hpp"

int main(int argc, char* argv[]) {
    MPI_Init(&argc, &argv);

    int world_rank = 0;
    int world_size = 1;
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);

    char proc_name[MPI_MAX_PROCESSOR_NAME];
    int name_len = 0;
    MPI_Get_processor_name(proc_name, &name_len);

    // Partition hardware threads evenly across MPI ranks on this node
    unsigned int hw_threads = std::thread::hardware_concurrency();
    if (hw_threads == 0) hw_threads = 24;
    unsigned int islands_per_rank = std::max(1u, hw_threads / static_cast<unsigned int>(world_size));
    unsigned int total_islands = islands_per_rank * static_cast<unsigned int>(world_size);

    unsigned int dimensions = 50;
    unsigned int population_size = 100;
    unsigned int gens_per_step = 2500;
    unsigned int evolve_steps = 10; // 25,000 generations per island

    // Offset seeds per rank so every MPI rank explores an independent trajectory space
    unsigned int algo_seed  = 42u + static_cast<unsigned int>(world_rank) * 1000u;
    unsigned int archi_seed = 12345u + static_cast<unsigned int>(world_rank) * 1000u;

    double goal_fitness         = 0.0;
    double max_allowed_fitness  = 1.0e-5;
    double max_allowed_distance = 1.0e-2;

    std::string banner(88, '=');
    std::string divider(88, '-');

    if (world_rank == 0) {
        std::cout << banner << "\n";
        std::cout << "MPI + PAGMO2 HYBRID BENCHMARK INTENT & EXPECTED OUTCOME\n";
        std::cout << banner << "\n";
        std::cout << "Goal: Minimize " << dimensions << "-D Rosenbrock function across "
                  << world_size << " MPI ranks x " << islands_per_rank << " islands/rank\n"
                  << "      (" << total_islands << " total islands, " << population_size
                  << " individuals/island, " << (gens_per_step * evolve_steps) << " gens/island).\n";
        std::cout << "Pass: All " << total_islands << " islands reach fitness < " << max_allowed_fitness
                  << " and ||x - x*||_2 < " << max_allowed_distance << "\n";
        std::cout << "Seed: Base algo_seed = 42 (+1000*rank), Base archi_seed = 12345 (+1000*rank)\n\n";
        std::cout << "Synchronizing MPI barrier and launching " << total_islands << " island threads...\n";
    }

    pagmo::rosenbrock raw_problem(dimensions);
    pagmo::problem prob(raw_problem);
    pagmo::de raw_algorithm(gens_per_step, 0.8, 0.9, 2, 1e-12, 1e-12, algo_seed);
    pagmo::algorithm algo(raw_algorithm);

    pagmo::archipelago archi(islands_per_rank, algo, prob, population_size, archi_seed);

    MPI_Barrier(MPI_COMM_WORLD);
    auto t_start = std::chrono::steady_clock::now();

    archi.evolve(evolve_steps);
    archi.wait_check();

    MPI_Barrier(MPI_COMM_WORLD);
    auto t_end = std::chrono::steady_clock::now();
    double local_elapsed_sec = std::chrono::duration<double>(t_end - t_start).count();

    // Collect local per-island metrics
    std::vector<double> local_f(islands_per_rank);
    std::vector<double> local_dist(islands_per_rank);
    std::vector<unsigned long long> local_fevals(islands_per_rank);
    std::vector<int> local_pass(islands_per_rank);

    for (unsigned int i = 0; i < islands_per_rank; ++i) {
        pagmo::population pop = archi[i].get_population();
        double f = pop.champion_f()[0];
        std::vector<double> x = pop.champion_x();

        double sq = 0.0;
        for (double xi : x) {
            double err = xi - 1.0;
            sq += err * err;
        }
        double dist = std::sqrt(sq);

        local_f[i]      = f;
        local_dist[i]   = dist;
        local_fevals[i] = pop.get_problem().get_fevals();
        local_pass[i]   = ((f < max_allowed_fitness) && (dist < max_allowed_distance)) ? 1 : 0;
    }

    // Gather all island results and hostnames onto Rank 0
    std::vector<double> all_f;
    std::vector<double> all_dist;
    std::vector<unsigned long long> all_fevals;
    std::vector<int> all_pass;
    std::vector<char> all_hosts;

    if (world_rank == 0) {
        all_f.resize(total_islands);
        all_dist.resize(total_islands);
        all_fevals.resize(total_islands);
        all_pass.resize(total_islands);
        all_hosts.resize(static_cast<std::size_t>(world_size) * MPI_MAX_PROCESSOR_NAME);
    }

    MPI_Gather(local_f.data(), static_cast<int>(islands_per_rank), MPI_DOUBLE,
               all_f.data(), static_cast<int>(islands_per_rank), MPI_DOUBLE, 0, MPI_COMM_WORLD);
    MPI_Gather(local_dist.data(), static_cast<int>(islands_per_rank), MPI_DOUBLE,
               all_dist.data(), static_cast<int>(islands_per_rank), MPI_DOUBLE, 0, MPI_COMM_WORLD);
    MPI_Gather(local_fevals.data(), static_cast<int>(islands_per_rank), MPI_UNSIGNED_LONG_LONG,
               all_fevals.data(), static_cast<int>(islands_per_rank), MPI_UNSIGNED_LONG_LONG, 0, MPI_COMM_WORLD);
    MPI_Gather(local_pass.data(), static_cast<int>(islands_per_rank), MPI_INT,
               all_pass.data(), static_cast<int>(islands_per_rank), MPI_INT, 0, MPI_COMM_WORLD);
    MPI_Gather(proc_name, MPI_MAX_PROCESSOR_NAME, MPI_CHAR,
               all_hosts.data(), MPI_MAX_PROCESSOR_NAME, MPI_CHAR, 0, MPI_COMM_WORLD);

    double max_wall_sec = 0.0;
    MPI_Reduce(&local_elapsed_sec, &max_wall_sec, 1, MPI_DOUBLE, MPI_MAX, 0, MPI_COMM_WORLD);

    int global_pass = 1;
    if (world_rank == 0) {
        std::cout << "All " << world_size << " MPI ranks (" << total_islands
                  << " islands) completed in " << std::fixed << std::setprecision(3)
                  << max_wall_sec << " s.\n\n";

        std::cout << banner << "\n";
        std::cout << "MPI RESULTS SUMMARY (MEASURED VS. GOAL)\n";
        std::cout << banner << "\n";
        std::cout << std::left
                  << std::setw(6)  << "Rank"
                  << std::setw(12) << "Host"
                  << std::setw(8)  << "Island"
                  << std::setw(15) << "Measured_f"
                  << std::setw(15) << "Diff (f-Goal)"
                  << std::setw(15) << "||x - x*||_2"
                  << std::setw(11) << "Fevals"
                  << "Status\n";
        std::cout << divider << "\n";

        unsigned long long total_fevals = 0;
        for (int r = 0; r < world_size; ++r) {
            const char* host_str = &all_hosts[static_cast<std::size_t>(r) * MPI_MAX_PROCESSOR_NAME];
            for (unsigned int i = 0; i < islands_per_rank; ++i) {
                std::size_t idx = static_cast<std::size_t>(r) * islands_per_rank + i;
                double diff_f = all_f[idx] - goal_fitness;
                total_fevals += all_fevals[idx];
                if (all_pass[idx] == 0) global_pass = 0;

                std::cout << std::left
                          << std::setw(6)  << r
                          << std::setw(12) << host_str
                          << std::setw(8)  << i
                          << std::scientific << std::setprecision(4)
                          << std::setw(15) << all_f[idx]
                          << std::showpos << std::setw(15) << diff_f << std::noshowpos
                          << std::setw(15) << all_dist[idx]
                          << std::defaultfloat << std::setw(11) << all_fevals[idx]
                          << (all_pass[idx] ? "PASS" : "FAIL") << "\n";
            }
        }

        double mevals_per_sec = (static_cast<double>(total_fevals) / 1.0e6) / max_wall_sec;
        std::cout << divider << "\n";
        std::cout << "MPI Ranks x Islands:  " << world_size << " x " << islands_per_rank
                  << " (" << total_islands << " total islands)\n";
        std::cout << "Total Fevals:         " << total_fevals
                  << " (" << std::fixed << std::setprecision(2) << mevals_per_sec << " M evals/sec)\n";
        std::cout << "Max Rank Wall-Clock:  " << std::fixed << std::setprecision(3) << max_wall_sec << " s\n";
        std::cout << "Overall Verification: " << (global_pass ? "SUCCESS" : "FAILURE") << "\n\n";

        telemetry::print_provenance(argc, argv);
    }

    MPI_Bcast(&global_pass, 1, MPI_INT, 0, MPI_COMM_WORLD);
    MPI_Finalize();
    return global_pass ? 0 : 1;
}
